#!/usr/bin/env python3
from collections import Counter
import re

def extract_emojis(text):
    # This regex pattern matches emoji sequences
    emoji_pattern = r'[\U0001F300-\U0001F9FF]'
    return re.findall(emoji_pattern, text)

def analyze_emojis(emojis):
    # Count frequencies
    freq = Counter(emojis)

    print("=== Emoji Analysis ===")
    print(f"\nTotal number of emojis: {len(emojis)}")
    print(f"Unique emojis count: {len(freq)}")

    print("\nUnique emojis in order of appearance:")
    unique_ordered = []
    for emoji in emojis:
        if emoji not in unique_ordered:
            unique_ordered.append(emoji)
    print(''.join(unique_ordered))

    print("\nFrequency of each emoji:")
    for emoji, count in freq.most_common():
        print(f"{emoji}: {count}")

    # Look for repeating patterns
    print("\nLooking for common sequences:")
    for length in range(2, 6):
        sequences = [''.join(emojis[i:i+length]) for i in range(len(emojis)-length+1)]
        seq_freq = Counter(sequences)
        common_seqs = seq_freq.most_common(3)
        if common_seqs[0][1] > 1:
            print(f"\nCommon {length}-emoji sequences:")
            for seq, count in common_seqs:
                if count > 1:
                    print(f"{seq}: {count} times")

def main():
    try:
        with open('/home/ctfplayer/ctf_files/emoji.txt', 'r', encoding='utf-8') as f:
            content = f.read()

        emojis = extract_emojis(content)
        analyze_emojis(emojis)

        # Check if total count matches common encodings
        total = len(emojis)
        print("\nPossible encoding matches:")
        if total % 8 == 0:
            print(f"Could be bytes/ASCII encoding ({total//8} characters)")
        if total % 7 == 0:
            print(f"Could be 7-bit encoding ({total//7} characters)")
        if total % 6 == 0:
            print(f"Could be base64-like encoding ({total//6} groups)")
        if total % 4 == 0:
            print(f"Could be 32-bit encoding ({total//4} integers)")

    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import re

def extract_emojis(text):
    emoji_pattern = r'[\U0001F300-\U0001F9FF]'
    return re.findall(emoji_pattern, text)

def map_to_hex():
    with open('/home/ctfplayer/ctf_files/emoji.txt', 'r', encoding='utf-8') as f:
        content = f.read()

    emojis = extract_emojis(content)
    unique_emojis = []
    for emoji in emojis:
        if emoji not in unique_emojis:
            unique_emojis.append(emoji)

    # Create mapping to hex
    hex_map = {emoji: format(i, 'x') for i, emoji in enumerate(unique_emojis)}

    # Convert emoji sequence to hex
    hex_sequence = ''.join(hex_map[emoji] for emoji in emojis)

    print("Emoji to Hex mapping:")
    for emoji, hex_val in hex_map.items():
        print(f"{emoji}: {hex_val}")

    print("\nHex sequence:")
    print(hex_sequence)

    # Try to convert hex to ASCII
    try:
        bytes_data = bytes.fromhex(hex_sequence)
        print("\nTrying ASCII conversion:")
        print(bytes_data.decode('ascii', errors='ignore'))
    except Exception as e:
        print(f"Error converting to ASCII: {e}")

if __name__ == "__main__":
    map_to_hex()

